function compressNewsImage(file){return new Promise((resolve,reject)=>{if(!file||!file.type.startsWith("image/")){reject(new Error("Lütfen geçerli bir görsel dosyası seçin."));return}if(file.size>15*1024*1024){reject(new Error("Seçilen dosya 15 MB sınırını aşıyor."));return}const objectUrl=URL.createObjectURL(file),img=new Image();img.onload=()=>{try{const maxSide=1280,scale=Math.min(1,maxSide/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext("2d");if(!ctx)throw new Error("Görsel düzenleyici başlatılamadı.");ctx.fillStyle="#ffffff";ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);let quality=.82,data=canvas.toDataURL("image/jpeg",quality);while(data.length*0.75>350*1024&&quality>.48){quality-=.08;data=canvas.toDataURL("image/jpeg",quality)}URL.revokeObjectURL(objectUrl);if(data.length*0.75>350*1024){reject(new Error("Görsel 350 KB altına küçültülemedi. Daha küçük bir görsel seçin."));return}resolve(data)}catch(err){URL.revokeObjectURL(objectUrl);reject(err)}};img.onerror=()=>{URL.revokeObjectURL(objectUrl);reject(new Error("Görsel açılamadı. Başka bir dosya deneyin."))};img.src=objectUrl})}
