    const coordinates=validCoordinates(latText,lngText);if(!coordinates.valid){alert("Enlem ve boylam birlikte girilmeli. Enlem -90 ile 90, boylam -180 ile 180 arasında olmalı.");return}
    let province=String(sites[id]?.province||""),district=String(sites[id]?.district||""),geocodeWarning="";
    if(!coordinates.empty){try{const location=await reverseGeocodeAddress(coordinates.latitude,coordinates.longitude);if(location.province)province=location.province;if(location.district)district=location.district;}catch(err){geocodeWarning=" Koordinatlar kaydedildi ancak Google Maps il/ilçe bulamadı: "+err.message}}
